mapper.select:
/* selectMasterMdCpUserChoicePop */ SELECT L.USER_ID, L.USER_NAME_LOC, L.DEPARTMENT, ( SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND CODE = L.DEPARTMENT AND TYPE = 'C001') DEPT_NAME, L.POSITION, ( SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND CODE = L.POSITION AND TYPE = 'C003') POSITION_NAME, L.EMAIL, L.ADDRESS_LOC, L.PHONE_NUMBER, L.FAX_NUMBER, L.CHANGE_USER_TYPE FROM ICOMLUSR L WHERE L.COM_CODE = #{st_buyer} AND L.STATUS <> 'D' AND (L.OFFICE_YN IS NULL OR L.OFFICE_YN <> 'Y' )
AND L.USER_ID LIKE UPPER('%' || #{st_user_id} || '%')
AND L.USER_NAME_LOC = #{st_user_name}
AND L.USER_NAME_LOC LIKE ('%' || #{st_user_name} || '%')
ORDER BY L.USER_NAME_LOC
